package com.nextaicommerce.platform.marketplace;
import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
import java.util.*;import org.junit.jupiter.api.*;import org.springframework.mock.web.MockHttpSession;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.web.server.ResponseStatusException;import com.nextaicommerce.platform.web.*;
class FbaInventoryRefreshPermissionTest {
 WorkspaceAccessRepository workspace=mock(WorkspaceAccessRepository.class);UUID tenant=UUID.randomUUID(),store=UUID.randomUUID();MockHttpSession session=new MockHttpSession();MarketplaceSkuController controller=new MarketplaceSkuController(mock(MarketplaceSkuRepository.class),workspace,mock(com.nextaicommerce.platform.catalog.CatalogRepository.class));
 @BeforeEach void setup(){session.setAttribute(AccountSelectionController.TENANT_ID,tenant);session.setAttribute(AccountSelectionController.STORE_ID,store);when(workspace.findConnection(tenant,store)).thenReturn(new WorkspaceAccessRepository.ConnectionIdentity(store,"AMAZON"));}
 @Test void cannotRefreshAnotherSelectedStore(){var actor=new UsernamePasswordAuthenticationToken("actor","",List.of(new SimpleGrantedAuthority("ROLE_OWNER")));assertThatThrownBy(()->controller.refreshInventory(UUID.randomUUID(),actor,session)).isInstanceOf(ResponseStatusException.class).hasMessageContaining("403");}
 @Test void readStatusRequiresAccountOperationPermission(){var actor=new UsernamePasswordAuthenticationToken("actor","",List.of());when(workspace.canOperateAccount(tenant,"actor")).thenReturn(false);assertThatThrownBy(()->controller.inventoryState(store,actor,session)).isInstanceOf(ResponseStatusException.class).hasMessageContaining("403");}
 @Test void forgedRoleDoesNotBypassActualMembership(){var actor=new UsernamePasswordAuthenticationToken("actor","",List.of(new SimpleGrantedAuthority("ROLE_OWNER")));when(workspace.canOperateAccount(tenant,"actor")).thenReturn(true);when(workspace.listAccountOptions("actor",false)).thenReturn(List.of());assertThatThrownBy(()->controller.refreshInventory(store,actor,session)).isInstanceOf(ResponseStatusException.class).hasMessageContaining("403");}
}
